        private static FctStudioProject BuildC96ElevenChapterLayout(FctStudioProject project, SequenceDocument sourceSequence)
        {
            GlobalModuleLibraryService.MergeInto(project); List<FunctionBlockDefinition> imported = project.Blocks.ToList(); project.Flow.Clear();
            FunctionBlockDefinition lowPower = CreateLowPowerIoModule();
            FunctionBlockDefinition initialization = imported.FirstOrDefault(value => value.Id == "c96-std-product-init") ?? PromoteImported(imported.FirstOrDefault(value => value.Name.IndexOf("初始化产品", StringComparison.OrdinalIgnoreCase) >= 0), "c96-std-product-init", "产品进入FT与通信初始化") ?? ExtractStandard(sourceSequence, "c96-std-product-init", "产品进入FT与通信初始化", step => step.StepName.IndexOf("产品进入FT", StringComparison.OrdinalIgnoreCase) >= 0);
            FunctionBlockDefinition faultClear = imported.FirstOrDefault(value => value.Id == "c96-std-clear-faults") ?? PromoteImported(imported.FirstOrDefault(value => value.Name.IndexOf("清除错误", StringComparison.OrdinalIgnoreCase) >= 0), "c96-std-clear-faults", "主驱故障清除") ?? ExtractStandard(sourceSequence, "c96-std-clear-faults", "主驱故障清除", step => step.StepName.IndexOf("清除错误", StringComparison.OrdinalIgnoreCase) >= 0);
            FunctionBlockDefinition tm1Current = imported.FirstOrDefault(value => value.Id == "c96-std-tm1-current") ?? PromoteImported(imported.FirstOrDefault(value => value.Name == "TM1三相出流与验证"), "c96-std-tm1-current", "TM1三相出流与验证");
            FunctionBlockDefinition tm2Current = imported.FirstOrDefault(value => value.Id == "c96-std-tm2-current") ?? PromoteImported(imported.FirstOrDefault(value => value.Name == "TM2三相出流与验证"), "c96-std-tm2-current", "TM2三相出流与验证");
            if (tm1Current == null) tm1Current = RebuildCurrentModule(sourceSequence, "TM1", "c96-std-tm1-current"); if (tm2Current == null) tm2Current = RebuildCurrentModule(sourceSequence, "TM2", "c96-std-tm2-current");
            List<FunctionBlockDefinition> baseReads = imported.Where(value => value.Id != null && value.Id.StartsWith("c96-std-base-read-", StringComparison.Ordinal)).OrderBy(value => value.Id).ToList(); if (baseReads.Count == 0) { baseReads = imported.Where(value => value.Name == "主驱基础状态读取").Take(6).ToList(); for (int i = 0; i < baseReads.Count; i++) PromoteImported(baseReads[i], "c96-std-base-read-" + (i + 1), "主驱基础状态读取" + (i + 1)); }

            FunctionBlockDefinition lvdc = CreateLvdcModule(); FunctionBlockDefinition analogRead = CreateAnalogInputsReadModule(); FunctionBlockDefinition resolverSpeed = CreateResolverSpeedModule(); FunctionBlockDefinition resolverPosition = CreateResolverPositionModule(); FunctionBlockDefinition motorTemperature = CreateMotorTemperatureModule(); FunctionBlockDefinition highVoltage = CreateHighVoltageMeasureModule(); FunctionBlockDefinition highFault = CreateHighVoltageFaultModule(); FunctionBlockDefinition cooling = CreateCoolingReadModule(); FunctionBlockDefinition thermalSnapshot = CreateThermalSnapshotModule(); FunctionBlockDefinition hvOn = CreateMachineHighVoltageOnModule(); FunctionBlockDefinition hvOff = CreateMachineHighVoltageOffModule(); FunctionBlockDefinition auxiliary = CreateAuxiliaryComprehensiveModule(); FunctionBlockDefinition placeholder = CreateReservedPlaceholderModule();
            List<FunctionBlockDefinition> atoms = new[] { lowPower, initialization, faultClear, tm1Current, tm2Current, lvdc, analogRead, resolverSpeed, resolverPosition, motorTemperature, highVoltage, highFault, cooling, thermalSnapshot, hvOn, hvOff, auxiliary, placeholder }.Where(value => value != null).Concat(baseReads).GroupBy(value => value.Id, StringComparer.Ordinal).Select(group => group.First()).ToList();
            foreach (FunctionBlockDefinition atom in atoms) ApplyCompactPlatformDefaults(atom);
            foreach (FunctionBlockDefinition atom in atoms) { project.Blocks.RemoveAll(value => value.Id == atom.Id); project.Blocks.Add(atom); TrySaveReusable(atom); }

            List<FunctionBlockDefinition> chapters = new List<FunctionBlockDefinition>();
            FunctionBlockDefinition chapter1 = Chapter("c96-chapter-01", "01 测前校验"); Ref(chapter1, lowPower); Ref(chapter1, initialization); Ref(chapter1, faultClear); chapters.Add(chapter1);
            FunctionBlockDefinition chapter2 = Chapter("c96-chapter-02", "02 低压信号测量"); foreach (double voltage in new[] { 18d, 24d, 32d }) { Ref(chapter2, lvdc, Pair("Voltage", voltage)); Ref(chapter2, analogRead); } chapters.Add(chapter2);
            FunctionBlockDefinition chapter3 = Chapter("c96-chapter-03", "03 双旋变模拟"); Ref(chapter3, resolverSpeed, Pairs("Speed", 700d, "LowLimit", 690d, "HighLimit", 710d)); Ref(chapter3, resolverSpeed, Pairs("Speed", 3500d, "LowLimit", 3470d, "HighLimit", 3530d)); Ref(chapter3, resolverSpeed, Pairs("Speed", 7000d, "LowLimit", 6970d, "HighLimit", 7030d)); foreach (double angle in new[] { 0d, 225d, 315d }) Ref(chapter3, resolverPosition, Pairs("Position", angle, "LowLimit", angle - 2d, "HighLimit", angle + 2d)); chapters.Add(chapter3);
            FunctionBlockDefinition chapter4 = Chapter("c96-chapter-04", "04 双电机温度模拟"); double[] resistances = { 842.71, 1097.335, 1308.9, 1479.5, 1666.2, 1097.335 }; double[] temperatures = { -40, 25, 80, 125, 175, 25 }; for (int channel = 1; channel <= 2; channel++) for (int i = 0; i < resistances.Length; i++) Ref(chapter4, motorTemperature, Pairs("Channel", channel, "Resistance", resistances[i], "TableIndex", channel == 1 ? 12 : 16, "LowLimit", temperatures[i] - 5, "HighLimit", temperatures[i] + 5)); chapters.Add(chapter4);
            FunctionBlockDefinition chapter5 = Chapter("c96-chapter-05", "05 辅驱与DCDC综合测试"); Ref(chapter5, lvdc, Pairs("Voltage", 24d, "Current", 5d)); Ref(chapter5, cooling, Pairs("DbNumber", 101, "ByteOffset", 578, "LowLimit", 27d, "HighLimit", 33d)); Ref(chapter5, hvOn, Pair("Voltage", 618d)); Ref(chapter5, auxiliary); Ref(chapter5, hvOff); chapters.Add(chapter5);
            FunctionBlockDefinition chapter6 = Chapter("c96-chapter-06", "06 高压精度与故障注入"); Ref(chapter6, hvOn, Pair("Voltage", 0d)); Ref(chapter6, highFault, Pair("ExpectedFault", 0)); foreach (double voltage in new[] { 0d, 100d, 200d, 300d, 400d }) Ref(chapter6, highVoltage, VoltageLimits(voltage)); Ref(chapter6, highFault, Pair("ExpectedFault", 1)); foreach (double voltage in new[] { 500d, 600d, 700d, 750d }) Ref(chapter6, highVoltage, VoltageLimits(voltage)); Ref(chapter6, highFault, Pair("ExpectedFault", 0)); Ref(chapter6, highVoltage, VoltageLimits(775d)); Ref(chapter6, highFault, Pair("ExpectedFault", 1)); Ref(chapter6, highVoltage, VoltageLimits(600d)); Ref(chapter6, highFault, Pair("ExpectedFault", 0)); Ref(chapter6, hvOff); chapters.Add(chapter6);
            FunctionBlockDefinition chapter7 = Chapter("c96-chapter-07", "07 冷却与测温初始值"); Ref(chapter7, cooling, Pairs("DbNumber", 101, "ByteOffset", 578, "LowLimit", 27d, "HighLimit", 33d)); Ref(chapter7, thermalSnapshot); chapters.Add(chapter7);
            FunctionBlockDefinition chapter8 = Chapter("c96-chapter-08", "08 额定电压电流精度"); Ref(chapter8, hvOn, Pair("Voltage", 618d)); foreach (double current in new[] { 0d, 100d, 200d, 300d, 400d, 500d, 600d, 700d, 850d }) { Dictionary<string, object> limits = CurrentLimits(current); Ref(chapter8, tm1Current, limits); Ref(chapter8, tm2Current, limits); } Ref(chapter8, hvOff); chapters.Add(chapter8);
            FunctionBlockDefinition chapter9 = Chapter("c96-chapter-09", "09 全工况拉载测温"); Ref(chapter9, thermalSnapshot); double[,] conditions = { { 18, 450, 630 }, { 16, 450, 850 }, { 18, 618, 630 }, { 16, 618, 850 }, { 18, 750, 630 }, { 18, 750, 850 } }; for (int row = 0; row < conditions.GetLength(0); row++) { Ref(chapter9, lvdc, Pair("Voltage", conditions[row, 0])); Ref(chapter9, hvOn, Pair("Voltage", conditions[row, 1])); Ref(chapter9, tm1Current, CurrentLimits(conditions[row, 2])); Ref(chapter9, tm2Current, CurrentLimits(conditions[row, 2])); Ref(chapter9, thermalSnapshot); Ref(chapter9, hvOff); } chapters.Add(chapter9);
            FunctionBlockDefinition chapter10 = Chapter("c96-chapter-10", "10 放电准备（预留）"); Ref(chapter10, placeholder, Pair("Description", "退出FT进入APP命令未确认")); chapters.Add(chapter10);
            FunctionBlockDefinition chapter11 = Chapter("c96-chapter-11", "11 被动放电（预留）"); Ref(chapter11, placeholder, Pair("Description", "C96放电DBC接口存在两套定义，确认后启用")); chapters.Add(chapter11);
            FunctionBlockDefinition chapter12 = Chapter("c96-chapter-12", "12 主动放电（预留）"); Ref(chapter12, placeholder, Pair("Description", "主动放电故障注入与命令未定义")); chapters.Add(chapter12);
            foreach (FunctionBlockDefinition chapter in chapters) { project.Blocks.RemoveAll(value => value.Id == chapter.Id); project.Blocks.Add(chapter); project.Flow.Add(new FlowBlockInstance { BlockId = chapter.Id, DisplayName = chapter.Name, Phase = ChapterPhase(chapter.Name), Snapshot = chapter.Clone(), ParameterOverrides = new Dictionary<string, object>(StringComparer.Ordinal) }); }
            project.ProjectName = "C96_FCT_12章主驱辅驱测试_A0"; return project;
        }

        private static FunctionBlockDefinition PromoteImported(FunctionBlockDefinition block, string id, string name) { if (block == null) return null; block.Id = id; block.Name = name; block.ModuleKind = "Standard"; block.IsStandard = true; block.Category = name.IndexOf("电流", StringComparison.OrdinalIgnoreCase) >= 0 ? "主驱" : "公共准备"; block.SupportedProducts = new List<string> { "C96" }; return block; }
        private static FunctionBlockDefinition ExtractStandard(SequenceDocument sequence, string id, string name, Func<SequenceStepDefinition, bool> predicate) { if (sequence == null) return null; List<SequenceStepDefinition> steps = sequence.Steps.Where(predicate).ToList(); if (steps.Count == 0) return null; FunctionBlockDefinition block = Standard(id, name, "公共准备"); foreach (SequenceStepDefinition source in steps) { SequenceStepDefinition step = SequenceEditing.Clone(source); int separator = step.StepName.LastIndexOf(" / ", StringComparison.Ordinal); if (separator >= 0) step.StepName = step.StepName.Substring(separator + 3); block.Steps.Add(new BlockStepDefinition { StepProperties = new Dictionary<string, object>(step.Properties, StringComparer.Ordinal) }); } return block; }
        private static FunctionBlockDefinition RebuildCurrentModule(SequenceDocument sequence, string drive, string id) { if (sequence == null) return null; List<SequenceStepDefinition> steps = sequence.Steps.Where(step => step.StepName.IndexOf("-" + drive + "三相出流与验证 /", StringComparison.OrdinalIgnoreCase) >= 0).Take(4).Select(SequenceEditing.Clone).ToList(); if (steps.Count != 4) return null; foreach (SequenceStepDefinition step in steps) { int separator = step.StepName.LastIndexOf(" / ", StringComparison.Ordinal); if (separator >= 0) step.StepName = step.StepName.Substring(separator + 3); } FunctionBlockDefinition block = BuildParameterizedCurrentBlock(steps, drive, 100d, "C96"); block.Id = id; block.Name = drive + "三相出流与验证"; block.ModuleKind = "Standard"; block.IsStandard = true; return block; }
        private static FunctionBlockDefinition Standard(string id, string name, string category) { return new FunctionBlockDefinition { Id = id, Name = name, Category = category, ModuleKind = "Standard", IsStandard = true, Version = "1.0", SupportedProducts = new List<string> { "C96" } }; }
        private static void ApplyCompactPlatformDefaults(FunctionBlockDefinition block) { if (block == null) return; foreach (BlockStepDefinition blockStep in block.Steps.Where(step => !step.IsModuleReference)) { SequenceStepDefinition step = blockStep.ToStep(); string resultMode = Convert.ToString(step.Get("ResultMode", "Action"), CultureInfo.InvariantCulture); bool force = Convert.ToBoolean(step.Get("ForcePlatformDisplay", false), CultureInfo.InvariantCulture); if (!force && (string.Equals(resultMode, "Action", StringComparison.OrdinalIgnoreCase) || string.Equals(resultMode, "Variable", StringComparison.OrdinalIgnoreCase))) blockStep.StepProperties["RecordingLog"] = false; } }
        private static FunctionBlockDefinition Chapter(string id, string name) { return new FunctionBlockDefinition { Id = id, Name = name, Category = "章节", ModuleKind = "Custom", IsStandard = false, Version = "1.0", SupportedProducts = new List<string> { "C96" } }; }
        private static void Ref(FunctionBlockDefinition chapter, FunctionBlockDefinition child, IDictionary<string, object> values = null) { if (chapter == null || child == null) return; BlockStepDefinition reference = new BlockStepDefinition { ReferencedBlockId = child.Id, ReferencedBlockName = child.Name, Enabled = true }; foreach (BlockParameterDefinition parameter in child.Parameters) reference.ReferencedParameterOverrides[parameter.Name] = parameter.DefaultValue; if (values != null) foreach (KeyValuePair<string, object> pair in values) reference.ReferencedParameterOverrides[pair.Key] = pair.Value; chapter.Steps.Add(reference); }
        private static BlockStepDefinition Step(string name, string function, IDictionary<string, object> values) { object resultMode; bool platformDisplay = values != null && values.TryGetValue("ResultMode", out resultMode) && !string.Equals(Convert.ToString(resultMode), "Action", StringComparison.OrdinalIgnoreCase) && !string.Equals(Convert.ToString(resultMode), "Variable", StringComparison.OrdinalIgnoreCase); Dictionary<string, object> properties = new Dictionary<string, object>(StringComparer.Ordinal) { { "StepName", name }, { "RunMode", "Normal" }, { "FunctionName", function }, { "RecordingLog", platformDisplay } }; foreach (KeyValuePair<string, object> pair in values) properties[pair.Key] = pair.Value; return new BlockStepDefinition { StepProperties = properties }; }
        private static void Parameter(FunctionBlockDefinition block, string name, string display, object value, string unit, string description = "") { block.Parameters.Add(new BlockParameterDefinition { Name = name, DisplayName = display, Type = value is int ? "int" : value is bool ? "bool" : value is string ? "string" : "double", DefaultValue = value, Unit = unit, Description = description, Required = true }); }
        private static FunctionBlockDefinition CreateLowPowerIoModule() { FunctionBlockDefinition b = Standard("c96-std-low-power", "低压供电与KL30-KL15切换", "公共准备"); b.Steps.Add(Step("功能板相关输出安全复位", "FCT_ExecuteAction", Pairs("Device", "RELAY_FCT", "Operation", "SetDO", "ResultMode", "Action", "Channels", "OUT6,OUT7,OUT9,OUT10,OUT30,OUT35", "Values", "0,0,0,0,0,0", "Slave", 1))); b.Steps.Add(Step("KL30电源设置24V", "FCT_ExecuteAction", Pairs("Device", "LVDC", "Operation", "SetVoltage", "ResultMode", "Action", "Voltage", 24d))); b.Steps.Add(Step("KL30电源限流5A", "FCT_ExecuteAction", Pairs("Device", "LVDC", "Operation", "SetCurrent", "ResultMode", "Action", "Current", 5d))); b.Steps.Add(Step("KL30电源输出打开", "FCT_ExecuteAction", Pairs("Device", "LVDC", "Operation", "SetOutput", "ResultMode", "Action", "Output", true))); b.Steps.Add(Step("功能板接通KL30电源与Sense", "FCT_ExecuteAction", Pairs("Device", "RELAY_FCT", "Operation", "SetDO", "ResultMode", "Action", "Channels", "OUT6", "Values", "1", "Slave", 1))); b.Steps.Add(Step("KL15电源设置24V", "FCT_ExecuteAction", Pairs("Device", "LVDC_KL15", "Operation", "SetVoltage", "ResultMode", "Action", "Voltage", 24d))); b.Steps.Add(Step("KL15电源限流5A", "FCT_ExecuteAction", Pairs("Device", "LVDC_KL15", "Operation", "SetCurrent", "ResultMode", "Action", "Current", 5d))); b.Steps.Add(Step("KL15电源输出打开", "FCT_ExecuteAction", Pairs("Device", "LVDC_KL15", "Operation", "SetOutput", "ResultMode", "Action", "Output", true))); b.Steps.Add(Step("功能板接通KL15A与KL15B", "FCT_ExecuteAction", Pairs("Device", "RELAY_FCT", "Operation", "SetDO", "ResultMode", "Action", "Channels", "OUT30,OUT35", "Values", "1,1", "Slave", 1))); b.Steps.Add(Step("低压路径稳定等待", "FCT_ExecuteLogic", Pairs("Operation", "Delay", "ResultMode", "Action", "TimeMs", 1000))); return b; }
        private static FunctionBlockDefinition CreateMachineHighVoltageOnModule() { FunctionBlockDefinition b = Standard("c96-std-machine-hv-on", "机台高压预充与主供电", "高压"); Parameter(b, "Voltage", "目标高压", 618d, "V"); Parameter(b, "PrechargeMs", "预充等待", 1000, "ms"); b.Steps.Add(Step("高压源设为0V", "FCT_ExecuteAction", Pairs("Device", "HVDC", "Operation", "SetVoltage", "ResultMode", "Action", "Voltage", 0d))); b.Steps.Add(Step("高压源输出打开", "FCT_ExecuteAction", Pairs("Device", "HVDC", "Operation", "SetOutput", "ResultMode", "Action", "Output", true))); b.Steps.Add(Step("机台KM1与KM2复位", "FCT_ExecuteAction", Pairs("Device", "RELAY_FCT", "Operation", "SetDO", "ResultMode", "Action", "Channels", "OUT36,OUT37", "Values", "0,0", "Slave", 1))); b.Steps.Add(Step("机台KM2预充接通", "FCT_ExecuteAction", Pairs("Device", "RELAY_FCT", "Operation", "SetDO", "ResultMode", "Action", "Channels", "OUT37", "Values", "1", "Slave", 1))); BlockStepDefinition wait = Step("等待预充", "FCT_ExecuteLogic", Pairs("Operation", "Delay", "ResultMode", "Action", "TimeMs", 1000)); wait.ParameterBindings["TimeMs"] = "PrechargeMs"; b.Steps.Add(wait); b.Steps.Add(Step("机台KM1主供电接通", "FCT_ExecuteAction", Pairs("Device", "RELAY_FCT", "Operation", "SetDO", "ResultMode", "Action", "Channels", "OUT36", "Values", "1", "Slave", 1))); b.Steps.Add(Step("释放机台KM2预充", "FCT_ExecuteAction", Pairs("Device", "RELAY_FCT", "Operation", "SetDO", "ResultMode", "Action", "Channels", "OUT37", "Values", "0", "Slave", 1))); BlockStepDefinition voltage = Step("设置目标高压", "FCT_ExecuteAction", Pairs("Device", "HVDC", "Operation", "SetVoltage", "ResultMode", "Action", "Voltage", 618d)); voltage.ParameterBindings["Voltage"] = "Voltage"; b.Steps.Add(voltage); b.Steps.Add(Step("高压稳定等待", "FCT_ExecuteLogic", Pairs("Operation", "Delay", "ResultMode", "Action", "TimeMs", 1000))); return b; }
        private static FunctionBlockDefinition CreateMachineHighVoltageOffModule() { FunctionBlockDefinition b = Standard("c96-std-machine-hv-off", "机台高压安全下电", "安全"); b.Steps.Add(Step("高压源降到0V", "FCT_ExecuteAction", Pairs("Device", "HVDC", "Operation", "SetVoltage", "ResultMode", "Action", "Voltage", 0d))); b.Steps.Add(Step("降压等待", "FCT_ExecuteLogic", Pairs("Operation", "Delay", "ResultMode", "Action", "TimeMs", 1000))); b.Steps.Add(Step("高压源输出关闭", "FCT_ExecuteAction", Pairs("Device", "HVDC", "Operation", "SetOutput", "ResultMode", "Action", "Output", false))); b.Steps.Add(Step("断开机台KM1与KM2", "FCT_ExecuteAction", Pairs("Device", "RELAY_FCT", "Operation", "SetDO", "ResultMode", "Action", "Channels", "OUT36,OUT37", "Values", "0,0", "Slave", 1))); b.Steps.Add(Step("关闭高压15选1", "FCT_ExecuteAction", Pairs("Device", "RELAY_HVMUX", "Operation", "Disable15", "ResultMode", "Action", "SwitchDelayMs", 50, "Slave", 1))); b.Steps.Add(Step("万用表切回低压档", "FCT_ExecuteAction", Pairs("Device", "RELAY_FCT", "Operation", "SetDO", "ResultMode", "Action", "Channels", "OUT45", "Values", "0", "Slave", 1))); return b; }
        private static FunctionBlockDefinition CreateAuxiliaryComprehensiveModule() { FunctionBlockDefinition b = Standard("c96-std-aux-comprehensive", "辅驱DCDC油泵气泵综合测试", "DCDC/辅驱"); Parameter(b, "DcdcLoadCurrent", "DCDC负载电流", 100d, "A"); Parameter(b, "OilCurrent", "油泵额定电流", 17d, "A"); Parameter(b, "AirCurrent", "气泵额定电流", 17d, "A"); Parameter(b, "Frequency", "辅驱频率", 50d, "Hz"); Parameter(b, "VfVoltage", "VF电压百分比", 1.9d, "%"); Parameter(b, "HoldTimeMs", "带载保持时间", 10000, "ms"); b.Steps.Add(Step("PDU主驱与共用回路100ms周期控制", "FCT_ExecuteAction", Pairs("Device", "AUXCAN", "Operation", "StartPeriodicDbc", "ResultMode", "Action", "PeriodicKey", "VCU_PDU", "PeriodMs", 100, "CanId", "0CF2503B", "DataHex", "01 00 01 00 00 00 00 00"))); b.Steps.Add(Step("PDU上电稳定等待", "FCT_ExecuteLogic", Pairs("Operation", "Delay", "ResultMode", "Action", "TimeMs", 2000))); foreach (string signal in new[] { "PowerIniDelay", "InitOver", "Init_FlagM0MPSuccess", "Init_FlagL0LPSuccess", "MotP_Volt", "LotP_Volt", "BUSVoltage", "DCDC_SwVer1", "DCDC_SwVer2", "DCDC_SwVer3", "DCDC_InVoltage", "DCDC_OutVoltage", "DCDC_OutCurrent", "DCDC_FaultCode", "OilPump_SwModelL", "OilPump_SwModelH", "OilPump_SwVer", "OilPump_RatedCurr", "OilPump_RatedPower", "OilPump_ModuleTemp", "AirPump_SwModelL", "AirPump_SwModelH", "AirPump_SwVer", "AirPump_RatedCurr", "AirPump_RatedPower", "AirPump_ModuleTemp" }) b.Steps.Add(AuxRead(signal)); BlockStepDefinition oil = Step("油泵17A-50Hz-VF1.9%周期启动", "FCT_ExecuteAction", Pairs("Device", "AUXCAN", "Operation", "StartPeriodicDbc", "ResultMode", "Action", "PeriodicKey", "OIL_PUMP", "PeriodMs", 100, "SignalsJson", "{\"DCDC_Start_Cmd\":170,\"DCAC_Steer_Start_Cmd\":85,\"DCAC_Steer_RatedCurr\":${OilCurrent},\"DCAC_Steer_FreqCmd\":${Frequency},\"DCAC_Steer_VF_Voltage\":${VfVoltage}}")); b.Steps.Add(oil); BlockStepDefinition holdOil = Step("油泵带载保持", "FCT_ExecuteLogic", Pairs("Operation", "Delay", "ResultMode", "Action", "TimeMs", 10000)); holdOil.ParameterBindings["TimeMs"] = "HoldTimeMs"; b.Steps.Add(holdOil); b.Steps.Add(DaqRead("油泵U相DAQ电流", "cDAQ1Mod4/ai0")); b.Steps.Add(DaqRead("油泵V相DAQ电流", "cDAQ1Mod4/ai1")); b.Steps.Add(DaqRead("油泵W相DAQ电流", "cDAQ1Mod4/ai2")); foreach (string signal in new[] { "OilPump_OutFreq", "OilPump_InVoltage", "OilPump_OutVoltage", "OilPump_OutCurrent", "OilPump_ModuleTemp", "OilPump_FaultCode" }) b.Steps.Add(AuxRead(signal)); b.Steps.Add(StopPeriodic("OIL_PUMP")); b.Steps.Add(Step("油泵停止命令", "FCT_ExecuteAction", Pairs("Device", "AUXCAN", "Operation", "SendDbcSignals", "ResultMode", "Action", "SignalsJson", "{\"DCDC_Start_Cmd\":170,\"DCAC_Steer_Start_Cmd\":170}"))); BlockStepDefinition air = Step("气泵17A-50Hz-VF1.9%周期启动", "FCT_ExecuteAction", Pairs("Device", "AUXCAN", "Operation", "StartPeriodicDbc", "ResultMode", "Action", "PeriodicKey", "AIR_PUMP", "PeriodMs", 100, "SignalsJson", "{\"DCAC_Air_Start_Cmd\":85,\"DCAC_Air_RatedCurr\":${AirCurrent},\"DCAC_Air_FreqCmd\":${Frequency},\"DCAC_Air_VF_Voltage\":${VfVoltage}}")); b.Steps.Add(air); BlockStepDefinition holdAir = Step("气泵带载保持", "FCT_ExecuteLogic", Pairs("Operation", "Delay", "ResultMode", "Action", "TimeMs", 10000)); holdAir.ParameterBindings["TimeMs"] = "HoldTimeMs"; b.Steps.Add(holdAir); b.Steps.Add(DaqRead("气泵U相DAQ电流", "cDAQ1Mod3/ai0")); b.Steps.Add(DaqRead("气泵V相DAQ电流", "cDAQ1Mod3/ai1")); b.Steps.Add(DaqRead("气泵W相DAQ电流", "cDAQ1Mod3/ai2")); foreach (string signal in new[] { "AirPump_OutFreq", "AirPump_InVoltage", "AirPump_OutVoltage", "AirPump_OutCurrent", "AirPump_ModuleTemp", "AirPump_FaultCode" }) b.Steps.Add(AuxRead(signal)); b.Steps.Add(StopPeriodic("AIR_PUMP")); b.Steps.Add(Step("气泵停止命令", "FCT_ExecuteAction", Pairs("Device", "AUXCAN", "Operation", "SendDbcSignals", "ResultMode", "Action", "SignalsJson", "{\"DCAC_Air_Start_Cmd\":170}"))); b.Steps.Add(Step("DCDC 100ms周期启动", "FCT_ExecuteAction", Pairs("Device", "AUXCAN", "Operation", "StartPeriodicDbc", "ResultMode", "Action", "PeriodicKey", "DCDC_COMMAND", "PeriodMs", 100, "SignalsJson", "{\"DCDC_Start_Cmd\":85,\"DCAC_Steer