        private static BlockStepDefinition AuxRead(string signal) { string unit = signal.IndexOf("Voltage", StringComparison.OrdinalIgnoreCase) >= 0 || signal.EndsWith("_Volt", StringComparison.OrdinalIgnoreCase) ? "V" : signal.IndexOf("Current", StringComparison.OrdinalIgnoreCase) >= 0 ? "A" : signal.IndexOf("Temp", StringComparison.OrdinalIgnoreCase) >= 0 ? "degC" : signal.IndexOf("Freq", StringComparison.OrdinalIgnoreCase) >= 0 ? "Hz" : string.Empty; return Step("读取" + signal, "FCT_ExecuteAction", Pairs("Device", "AUXCAN", "Operation", "ReadDbcSignal", "ResultMode", "Information", "SignalName", signal, "TimeoutMs", 1000, "Unit", unit)); }
