        private static FunctionBlockDefinition CreateMotorTemperatureModule() { FunctionBlockDefinition b = Standard("c96-std-motor-temp", "电机温度模拟与读取", "温度"); Parameter(b, "Channel", "电阻通道", 1, ""); Parameter(b, "Resistance", "模拟电阻", 1097.335d, "ohm"); Parameter(b, "TableIndex", "产品信号偏移", 12, "byte"); Parameter(b, "LowLimit", "温度下限", 20d, "degC"); Parameter(b, "HighLimit", "温度上限", 30d, "degC"); BlockStepDefinition set = Step("设置温度模拟电阻", "FCT_ExecuteAction", Pairs("Device", "RES", "Operation", "SetResistance", "ResultMode", "Action", "ResValue", 1097.335d, "Channel", 1)); set.ParameterBindings["ResValue"] = "Resistance"; set.ParameterBindings["Channel"] = "Channel"; BlockStepDefinition read = Step("读取产品电机温度", "FCT_CANSignal", Pairs("Operation", "Read", "ResultMode", "NumericLimit", "AddrOffset", 0, "TableIndex", 12, "DataSize", 4, "DataType", "float32", "LowLimit", 20d, "HighLimit", 30d, "Comtype", "GELE", "Unit", "degC")); read.ParameterBindings["TableIndex"] = "TableIndex"; read.ParameterBindings["LowLimit"] = "LowLimit"; read.ParameterBindings["HighLimit"] = "HighLimit"; b.Steps.Add(set); b.Steps.Add(read); return b; }
        private static FunctionBlockDefinition CreateHighVoltageMeasureModule() { FunctionBlockDefinition b = Standard("c96-std-hv-measure", "高压设定与双重读取", "高压"); Parameter(b, "Voltage", "目标高压", 600d, "V"); Parameter(b, "LowLimit", "电压下限", 582d, "V"); Parameter(b, "HighLimit", "电压上限", 618d, "V"); Parameter(b, "MeasurementChannel", "高压测量通道", 1, "HV"); BlockStepDefinition set = Step("设置高压", "FCT_ExecuteAction", Pairs("Device", "HVDC", "Operation", "SetVoltage", "ResultMode", "Action", "Voltage", 600d)); set.ParameterBindings["Voltage"] = "Voltage"; b.Steps.Add(set); b.Steps.Add(Step("万用表切换高压测量档", "FCT_ExecuteAction", Pairs("Device", "RELAY_FCT", "Operation", "SetDO", "ResultMode", "Action", "Channels", "OUT45", "Values", "1", "Slave", 1))); BlockStepDefinition mux = Step("高压15选1安全选择", "FCT_ExecuteAction", Pairs("Device", "RELAY_HVMUX", "Operation", "Select15", "ResultMode", "Action", "Selection", 1, "SwitchDelayMs", 50, "Slave", 1)); mux.ParameterBindings["Selection"] = "MeasurementChannel"; b.Steps.Add(mux); b.Steps.Add(Step("DMM配置直流高压", "FCT_ExecuteAction", Pairs("Device", "DMM", "Operation", "ConfigDCVoltage", "ResultMode", "Action", "Range", 1000d, "Solution", 0.01d))); BlockStepDefinition dmm = Step("DMM读取高压", "FCT_ExecuteAction", Pairs("Device", "DMM", "Operation", "Read", "ResultMode", "NumericLimit", "LowLimit", 582d, "HighLimit", 618d, "Comtype", "GELE", "Unit", "V")); dmm.ParameterBindings["LowLimit"] = "LowLimit"; dmm.ParameterBindings["HighLimit"] = "HighLimit"; BlockStepDefinition dut = Step("产品读取母线高压", "FCT_CANSignal", Pairs("Operation", "Read", "ResultMode", "NumericLimit", "AddrOffset", 0, "TableIndex", 32, "DataSize", 4, "DataType", "float32", "LowLimit", 582d, "HighLimit", 618d, "Comtype", "GELE", "Unit", "V")); dut.ParameterBindings["LowLimit"] = "LowLimit"; dut.ParameterBindings["HighLimit"] = "HighLimit"; b.Steps.Add(dmm); b.Steps.Add(dut); return b; }
