        private static Dictionary<string, object> Pair(string name, object value) { return new Dictionary<string, object>(StringComparer.Ordinal) { { name, value } }; }
        private static Dictionary<string, object> Pairs(params object[] values) { Dictionary<string, object> result = new Dictionary<string, object>(StringComparer.Ordinal); for (int i = 0; i + 1 < values.Length; i += 2) result[Convert.ToString(values[i], CultureInfo.InvariantCulture)] = values[i + 1]; return result; }
        private static Dictionary<string, object> CurrentLimits(double current) { return Pairs("TargetCurrent", current, "CurrentLow", current == 0 ? -10d : current * 0.99, "CurrentHigh", current == 0 ? 10d : current * 1.01, "ImbalanceHigh", current == 0 ? 10d : Math.Max(10d, current * 0.02)); }
        private static Dictionary<string, object> VoltageLimits(double voltage) { double tolerance = voltage == 0 ? 5d : Math.Abs(voltage) * 0.03; return Pairs("Voltage", voltage, "LowLimit", Math.Max(0, voltage - tolerance), "HighLimit", voltage + tolerance); }
        private static string ChapterPhase(string name) { if (name.StartsWith("10") || name.StartsWith("11") || name.StartsWith("12")) return "安全收尾"; if (name.StartsWith("05")) return "辅驱测试"; if (name.StartsWith("08") || name.StartsWith("09")) return "主驱测试"; return "准备阶段"; }
        private static void TrySaveReusable(FunctionBlockDefinition block) { try { GlobalModuleLibraryService.Save(block); } catch { } }
